/** Shared API types for yimeng Core (generated by hand from openapi; keep in sync). */

export type ID = string;

export interface ErrorBody {
  error: string;
  message: string;
}

export interface Page<T> {
  items: T[];
  total: number;
  limit: number;
  offset: number;
}

export interface Artist {
  id: ID;
  name: string;
  sort_name?: string;
  mb_id?: string;
  album_count: number;
  track_count: number;
}

export interface Album {
  id: ID;
  title: string;
  artist_name: string;
  artists: ArtistRef[];
  year?: number;
  genre?: string;
  track_count: number;
  disc_count?: number;
  duration_ms: number;
  has_cover: boolean;
  favorite?: boolean;
  rating?: number;
  created_at: string;
}

export interface ArtistRef {
  id: ID;
  name: string;
  role: string;
}

export interface Track {
  id: ID;
  title: string;
  artist_name: string;
  artists: ArtistRef[];
  album_id?: ID;
  album_title?: string;
  disc_no?: number;
  track_no?: number;
  year?: number;
  genre?: string;
  duration_ms: number;
  format?: string;
  play_count?: number;
  favorite?: boolean;
  rating?: number;
  created_at: string;
}

export interface PlayerState {
  player_id: ID;
  transport: "idle" | "buffering" | "playing" | "paused";
  position_ms: number;
  updated_at: string;
  current_index: number;
  queue_length: number;
  repeat: "off" | "all" | "one";
  shuffle: boolean;
  online?: boolean;
  sleep_until?: string;
  track?: TrackRef;
}

export interface TrackRef {
  id: ID;
  title: string;
  artist_name: string;
  album_id?: ID;
  album_title?: string;
  duration_ms: number;
}

export interface SystemInfo {
  version: string;
  uptime_s: number;
  features: Record<string, boolean>;
}

export interface HealthReport {
  tracks: number;
  albums: number;
  artists: number;
  missing_files: number;
  no_cover_albums: number;
  no_genre_tracks: number;
  by_format: Record<string, number>;
}

export interface Stats {
  tracks: number;
  albums: number;
  artists: number;
  play_count: number;
  favorites: number;
  playlists: number;
  top_artists: StatItem[];
  top_tracks: StatItem[];
}

export interface StatItem {
  id: ID;
  name: string;
  count: number;
}
